// Gera assinatura SHA256 para Shopee Affiliate Open API
const crypto = require('crypto');
const appId = $env.SHOPEE_APP_ID;
const secret = $env.SHOPEE_SECRET;
const items = [];

for (const item of $input.all()) {
  const { categoryId, categoryName } = item.json;
  const timestamp = Math.floor(Date.now() / 1000);

  const query = `
    query GetOffers($input: ProductOfferV2Input!) {
      productOfferV2(input: $input) {
        nodes {
          itemId
          productName
          priceMin
          priceMax
          priceDiscountRate
          sales
          ratingStar
          imageUrl
          shopeeUrl
          offerLink
        }
        pageInfo { page size hasNextPage }
      }
    }
  `;

  const variables = {
    input: {
      categoryIds: [categoryId],
      sortType: 2, // Sort by commission
      page: 1,
      limit: 50,
      minCommissionRate: 1
    }
  };

  const payload = JSON.stringify({ query, variables });
  const raw = `${appId}${timestamp}${payload}${secret}`;
  const signature = crypto.createHash('sha256').update(raw).digest('hex');

  items.push({
    json: { categoryName, categoryId, payload, timestamp, signature, appId }
  });
}

return items;

const crypto = require('crypto');
const items = [];

for (const item of $input.all()) {
  const nodes = item.json.data?.productOfferV2?.nodes || [];

  for (const product of nodes) {
    const shopeeId = String(product.itemId || '');
    const title = (product.productName || '').slice(0, 500);
    const urlOriginal = product.shopeeUrl || product.offerLink || '';
    const priceCurrent = product.priceMin || 0;
    const discountPct = product.priceDiscountRate
      ? Math.round(parseFloat(product.priceDiscountRate) * 100)
      : null;
    const rating = product.ratingStar ? parseFloat(product.ratingStar) : null;
    const imageUrl = product.imageUrl || null;

    if (priceCurrent <= 0 || !urlOriginal) continue;

    const hashInput = (urlOriginal + shopeeId).toLowerCase().trim();
    const hashDedup = crypto.createHash('sha256').update(hashInput).digest('hex');

    items.push({
      json: {
        source: 'shopee',
        external_id: shopeeId,
        hash_dedup: hashDedup,
        title,
        url_original: urlOriginal,
        store: 'shopee',
        price_current: priceCurrent,
        discount_pct: discountPct,
        rating,
        image_url: imageUrl,
        raw_payload: product,
      }
    });
  }
}

return items;
